<x-layouts.app :heading="$user->exists ? 'Edit user' : 'New user'"><form class="panel form-grid" method="post" action="{{ $user->exists ? route('users.update',$user) : route('users.store') }}">@csrf @if($user->exists)@method('PUT')@endif<label>Name<input name="name" value="{{ old('name',$user->name) }}" required></label><label>Email<input type="email" name="email" value="{{ old('email',$user->email) }}" required></label><label>Password<input type="password" name="password" {{ $user->exists ? '' : 'required' }}><small>{{ $user->exists?'Leave blank to retain password.':'At least 12 chars, mixed case and number.' }}</small></label><label>Confirm password<input type="password" name="password_confirmation"></label><fieldset class="wide"><legend>Roles</legend>@foreach($roles as $role)<label class="check"><input type="checkbox" name="roles[]" value="{{ $role->id }}" @checked(in_array($role->id,old('roles',$user->roles->pluck('id')->all())))> {{ $role->label }}</label>@endforeach</fieldset><label class="check wide"><input type="hidden" name="is_active" value="0"><input type="checkbox" name="is_active" value="1" @checked(old('is_active',$user->is_active ?? true))> Account active</label><div class="wide form-actions"><a class="btn" href="{{ route('users.index') }}">Cancel</a><button class="btn primary">Save user</button></div></form></x-layouts.app>
